// The wire between builds and its compatibility rule (P5 O1 M6, OX1; docs/doperpowers/plans/2026-10-27-p5-o1-seams.md).
// Two builds of one wire major interoperate. A change within the major is additive: a new command, a new event, a new
// optional property of an object schema at any depth, or a new capability. Everything else takes a major: a removed
// command, event, property or capability; a new socket or envelope message kind (an older peer closes the connection on
// a line it cannot read, where an unknown command answers `unknown_command` and an unknown event is dropped); a property
// made required or made optional; a changed type, `const`, `enum` or union member set (an added enum member included,
// since an older reader refuses it); a changed numeric, length or pattern bound; a changed `additionalProperties`; a
// changed owner; any change but an annotation to a protocol-2 form (V2_LINK below). An additive change bumps
// WIRE_MINOR, so a peer can tell what the other knows; an optional behaviour a peer of the same major may lack is a
// capability, `<area>.<feature>`.
//
// The manifest (wire-manifest.json, generated by `pnpm wire:manifest`, held by wire.test.ts) records the wire at the
// latest minor: every command owned by `engine-host`, `pty-host` or `machine` (input and output), every event in
// HOST_EVENTS, PTY_HOST_EVENTS and MACHINE_EVENTS, C1's envelope and the socket layer's own messages, and
// WIRE_CAPABILITIES. Main-to-renderer traffic stays out. A namespace O3 retags `machine` joins it as added commands. P5 O2
// M4: the pty host joined (it had stayed out as always the app's own build), since under the daemon shape it is `mawsd`'s
// build, which may be another; its binary `pty.data` frame is no line, so it has no entry of its own: the capability that
// gates it does. P5 O3-D M1 (docs/doperpowers/plans/2026-10-29-p5-o3-d-cutover.md, Interfaces §I): the machine host's
// event list joined beside the other two (a name in two lists is one entry, one schema), and WIRE_CAPABILITIES became the
// union of every capability a peer of this major may list; each peer lists only its own (PEER_CAPABILITIES).
//
// Later hellos (RL2, the hub's; O10 and O11) build on `classifyWireChange`'s rule.
import * as z from 'zod';
import {
  SOCKET_PROTOCOL,
  ATTACHMENT_CAPABILITY,
  CONNECTORS_CAPABILITY,
  CONNECTORS_CLIENT_CAPABILITY,
  HOLDER_CAPABILITY,
  MACHINE_ARTIFACTS_CAPABILITY,
  MACHINE_SPINE_CAPABILITY,
  PTY_FRAMES_CAPABILITY,
  RENDER_CLIENT_CAPABILITY,
  MACHINE_RENDER_CAPABILITY, // P5 O5 M4
  HOST_RENDER_CAPABILITY, // P5 O5 M4
  HOST_BROWSER_WORK_CAPABILITY, // P5 O17
  BROWSER_ENGINE_CAPABILITY, // P5 O17 M4
  MACHINE_DELIVERY_CAPABILITY, // P5 O7 M5c
  FOLLOW_OWNERS_CAPABILITY, // P5 O7 M8
  ENGINE_ROUTE_MACHINE_CAPABILITY, // P5 O7 M9
  MACHINE_PROJECT_ACTS_CAPABILITY, // the project registry's M12
  ClientExitSchema,
  ClientHelloSchema,
  ClientHelloV2Schema,
  DocumentsClosedSchema,
  DocumentsCloseSchema,
  DocumentsOpenSchema,
  ServerRefuseSchema,
  ServerWelcomeSchema,
  ServerWelcomeV2Schema,
} from '../host/socket-protocol';
import { HostClientGoneSchema, HostDocSchema, HostEventSchema, HostReadySchema, HostRequestSchema, HostRequestV2Schema, HostResponseSchema } from './host-protocol';
import type { WireRegistry } from './registry';

export const WIRE_MAJOR: number = SOCKET_PROTOCOL;
